package dk.stream.android;

import android.content.*;
import com.google.android.gms.cast.*;
import com.google.android.gms.cast.framework.*;
import com.google.android.gms.cast.framework.media.RemoteMediaClient;
import java.util.*;

/** Common Cast transport and receiver metadata for radio, streams and local documents. */
@androidx.media3.common.util.UnstableApi
public final class CastPlayback {
 private static Context application;
 private static RadioStation artworkStation;private static String artworkFile;private static byte[] artworkData;
 private static final Map<String,byte[]> fileCovers=new LinkedHashMap<>();private static boolean localLoadPending;
 private static CastQueuePlan queuePlan;private static MediaQueueItem[] queueItems;private static boolean appending;
 private static LocalQueue pendingPhoneQueue;
 private static LocalQueue castQueue;private static Playlist.Channel castChannel;private static String castChannelUrl;
 private static Runnable resumeAfterCast;private static boolean closingApp;
 private static CastContext cast;
 private static RemoteMediaClient watched;
 private static final RemoteMediaClient.Callback changes=new RemoteMediaClient.Callback(){@Override public void onStatusUpdated(){CastHistory.capture(true);appendFiles();}};
 private static final Map<String,String> localUrls=new HashMap<>();
 public static void init(Context context) {
  if(application!=null)return;application=context.getApplicationContext();
  try {cast=CastContext.getSharedInstance(application);cast.getSessionManager().addSessionManagerListener(new SessionManagerListener<CastSession>() {
   public void onSessionStarted(CastSession session,String id){closingApp=false;resumeAfterCast=null;castCurrent();}
   public void onSessionResumed(CastSession session,boolean suspended){closingApp=false;resumeAfterCast=null;}
   public void onSessionEnded(CastSession session,int error){beginSelection();resetFileQueue();localLoadPending=false;fileCovers.clear();Runnable resume=closingApp?null:resumeAfterCast;resumeAfterCast=null;castQueue=null;castChannel=null;castChannelUrl=null;localUrls.clear();artworkStation=null;artworkFile=null;artworkData=null;application.stopService(new Intent(application,LocalCastService.class));if(resume!=null)resume.run();}
   public void onSessionStarting(CastSession session){}public void onSessionStartFailed(CastSession session,int error){}public void onSessionEnding(CastSession session){if(!closingApp&&resumeAfterCast==null)resumeAfterCast=phonePlayback(application,session.getRemoteMediaClient());}public void onSessionResuming(CastSession session,String id){}public void onSessionResumeFailed(CastSession session,int error){}public void onSessionSuspended(CastSession session,int reason){}
  },CastSession.class);}catch(RuntimeException unavailable){cast=null;}
 }
 public static CastSession session(Context context){init(context);CastSession session=cast==null?null:cast.getSessionManager().getCurrentCastSession();return session!=null&&session.isConnected()?session:null;}
 public static boolean connected(Context context){return session(context)!=null;}
 static boolean retainedSession(Context context){init(context);return cast!=null&&cast.getSessionManager().getCurrentCastSession()!=null;}
 public static RemoteMediaClient remote(Context context){CastSession session=session(context);RemoteMediaClient remote=session==null?null:session.getRemoteMediaClient();if(watched!=remote){if(watched!=null)watched.unregisterCallback(changes);watched=remote;if(remote!=null)remote.registerCallback(changes);}if(remote!=null)CastHistory.start(context);return remote;}
 private static boolean isImageInfo(MediaInfo info){return info!=null&&(info.getContentType()!=null&&info.getContentType().startsWith("image/")||info.getMetadata()!=null&&info.getMetadata().getMediaType()==MediaMetadata.MEDIA_TYPE_PHOTO);}
 public static boolean image(Context context){RemoteMediaClient remote=remote(context);return remote!=null&&isImageInfo(remote.getMediaInfo())&&localUrls.containsValue(remote.getMediaInfo().getContentId());}
 public static String currentImageUri(Context context){if(!image(context))return null;String url=remote(context).getMediaInfo().getContentId();for(Map.Entry<String,String> entry:localUrls.entrySet())if(entry.getValue().equals(url))return entry.getKey();return null;}
 public static boolean hasMedia(Context context){RemoteMediaClient remote=remote(context);return remote!=null&&remote.getMediaInfo()!=null&&(remote.getPlayerState()!=MediaStatus.PLAYER_STATE_IDLE||image(context));}
 public static boolean audio(Context context){RemoteMediaClient remote=remote(context);MediaInfo info=remote==null?null:remote.getMediaInfo();return info!=null&&(info.getContentType()!=null&&info.getContentType().startsWith("audio/")||info.getMetadata()!=null&&info.getMetadata().getMediaType()==MediaMetadata.MEDIA_TYPE_MUSIC_TRACK);}
 public static String title(Context context){RemoteMediaClient remote=remote(context);MediaInfo info=remote==null?null:remote.getMediaInfo();return info==null||info.getMetadata()==null?"Stream":Objects.toString(info.getMetadata().getString(MediaMetadata.KEY_TITLE),"Stream");}
 public static boolean currentLocal(Context context,String uri){RemoteMediaClient remote=remote(context);return remote!=null&&(remote.getPlayerState()!=MediaStatus.PLAYER_STATE_IDLE||image(context))&&remote.getMediaInfo()!=null&&Objects.equals(localUrls.get(uri),remote.getMediaInfo().getContentId());}
 public static boolean pcloud(Context context){for(String uri:localUrls.keySet())if(PcloudDocument.is(uri)&&currentLocal(context,uri))return true;return false;}
 public static boolean playingLocal(Context context,String uri){RemoteMediaClient remote=remote(context);return currentLocal(context,uri)&&remote!=null&&(remote.isPlaying()||remote.isBuffering());}
 /** Route physical volume keys to the receiver while a Cast session is connected. */
 public static boolean volumeKey(Context context,android.view.KeyEvent event){
  int key=event.getKeyCode();if(key!=android.view.KeyEvent.KEYCODE_VOLUME_UP&&key!=android.view.KeyEvent.KEYCODE_VOLUME_DOWN&&key!=android.view.KeyEvent.KEYCODE_VOLUME_MUTE)return false;
  CastSession session=session(context);if(session==null)return false;
  if(event.getAction()==android.view.KeyEvent.ACTION_DOWN)try{
   if(key==android.view.KeyEvent.KEYCODE_VOLUME_MUTE){if(event.getRepeatCount()==0)session.setMute(!session.isMute());}
   else {double volume=session.getVolume();if(Double.isNaN(volume))return true;session.setVolume(Math.max(0,Math.min(1,volume+(key==android.view.KeyEvent.KEYCODE_VOLUME_UP?0.05:-0.05))));if(key==android.view.KeyEvent.KEYCODE_VOLUME_UP&&session.isMute())session.setMute(false);}
  }catch(java.io.IOException|IllegalStateException error){android.util.Log.w("StreamCast","Could not change receiver volume",error);}
  return true;
 }
 public static void toggle(Context context){RemoteMediaClient remote=remote(context);if(remote!=null){if(remote.isPlaying()||remote.isBuffering()){if(remote.isLiveStream())remote.stop();else remote.pause();}else if(remote.isLiveStream()&&remote.getMediaInfo()!=null)remote.load(new MediaLoadRequestData.Builder().setMediaInfo(remote.getMediaInfo()).setAutoplay(true).build());else remote.play();}}
 private static final java.util.concurrent.atomic.AtomicInteger selections=new java.util.concurrent.atomic.AtomicInteger();
 static int beginSelection(){return selections.incrementAndGet();}
 static int selection(){return selections.get();}
 static boolean selectionCurrent(int token){return token==selections.get();}
 private static int fileJumpGeneration;
 private static void resetFileQueue(){fileJumpGeneration++;queuePlan=null;queueItems=null;appending=false;}
 private static void appendFiles(){CastQueuePlan plan=queuePlan;MediaQueueItem[] items=queueItems;if(plan==null||items==null||localLoadPending||!plan.hasNext()||appending||application==null)return;RemoteMediaClient remote=remote(application);if(remote==null||remote.getMediaStatus()==null)return;MediaStatus status=remote.getMediaStatus();Integer index=status.getIndexById(status.getCurrentItemId());if(index==null||status.getQueueItemCount()-index>5)return;int from=plan.nextFrom(),to=plan.nextTo();appending=true;remote.queueInsertItems(Arrays.copyOfRange(items,from,to),MediaQueueItem.INVALID_ITEM_ID,null).setResultCallback(result->{if(queuePlan!=plan)return;appending=false;if(result.getStatus().isSuccess())plan.accepted(from,to);});}
 static Boolean canMoveFile(RemoteMediaClient remote,int direction){int index=fileIndex(remote);return index<0?null:direction<0?index>0:index+1<castQueue.entries.size();}
 static boolean moveFile(RemoteMediaClient remote,int direction){int index=fileIndex(remote);if(index<0)return false;int target=index+(direction<0?-1:1);if(target>=0&&target<castQueue.entries.size())playLocal(application,castQueue.entries.get(target),castQueue.entries,0);return true;}
 private static int fileIndex(RemoteMediaClient remote){if(castQueue==null||remote==null||remote.getMediaInfo()==null)return -1;String url=remote.getMediaInfo().getContentId();for(int index=0;index<castQueue.entries.size();index++)if(Objects.equals(url,localUrls.get(castQueue.entries.get(index).uri)))return index;return -1;}
 public static void releaseLocalServer(Context context){localUrls.clear();context.stopService(new Intent(context,LocalCastService.class));}
 public static void stopCasting(Context context){beginSelection();CastSession session=session(context);if(session==null)return;closingApp=false;resumeAfterCast=phonePlayback(context.getApplicationContext(),session.getRemoteMediaClient());cast.getSessionManager().endCurrentSession(true);}
 static LocalQueue takePhoneQueue(){LocalQueue queue=pendingPhoneQueue;pendingPhoneQueue=null;return queue;}
 static void streamLoaded(Playlist.Channel channel,String url){resetFileQueue();castChannel=channel;castChannelUrl=url;castQueue=null;artworkStation=null;artworkFile=null;artworkData=null;}
 private static Runnable phonePlayback(Context context,RemoteMediaClient remote){
  if(remote==null||remote.getMediaInfo()==null||remote.getPlayerState()==MediaStatus.PLAYER_STATE_IDLE&&!isImageInfo(remote.getMediaInfo()))return null;
  CastHistory.stop();MediaInfo info=remote.getMediaInfo();String url=info.getContentId();long position=remote.isLiveStream()?0:Math.max(0,remote.getApproximateStreamPosition());
  if(castQueue!=null){LocalQueue queue=castQueue;for(LocalMedia file:queue.entries)if(Objects.equals(localUrls.get(file.uri),url)){
   if(file.image())return ()->{ImageSession.select(file.uri);};
   if(!file.audio())return ()->{pendingPhoneQueue=new LocalQueue(queue.entries,file);context.startActivity(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("resumeCastFile",true).putExtra("resumeCastPosition",position));};
   return ()->{try{androidx.core.content.ContextCompat.startForegroundService(context,LocalAudioService.playIntent(context,file,queue.entries).putExtra("position",position));}catch(RuntimeException error){android.util.Log.e("StreamCast","Could not resume local media",error);}};
  }}
  if(artworkStation!=null&&Objects.equals(artworkStation.url,url)){RadioStation station=artworkStation;return ()->{try{androidx.core.content.ContextCompat.startForegroundService(context,RadioPlaybackService.playIntent(context,station));}catch(RuntimeException error){android.util.Log.e("StreamCast","Could not resume radio",error);}};}
  Playlist.Channel channel=castChannel;if(channel!=null&&Objects.equals(castChannelUrl,url))return ()->{Intent intent=new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("resumeCastUrl",channel.url).putExtra("resumeCastName",channel.name).putExtra("resumeCastLogo",channel.logoUrl).putExtra("resumeCastKind",channel.kind.name()).putExtra("resumeCastPosition",position);context.startActivity(intent);};
  return null;
 }
 public static void closeWithApp(Context context){beginSelection();resetFileQueue();localLoadPending=false;fileCovers.clear();closingApp=true;resumeAfterCast=null;CastHistory.stop();if(cast!=null)cast.getSessionManager().endCurrentSession(true);artworkStation=null;artworkFile=null;artworkData=null;localUrls.clear();context.stopService(new Intent(context,LocalCastService.class));}
 public static void stop(Context context){beginSelection();resetFileQueue();localLoadPending=false;fileCovers.clear();resumeAfterCast=null;castQueue=null;castChannel=null;CastHistory.beforeLoad();artworkStation=null;artworkFile=null;artworkData=null;RemoteMediaClient remote=remote(context);if(remote!=null)remote.stop();context.stopService(new Intent(context,LocalCastService.class));localUrls.clear();}
 public static boolean castCurrent(){if(ImageSession.viewing()){if(android.os.Build.VERSION.SDK_INT>=37&&application.checkSelfPermission("android.permission.ACCESS_LOCAL_NETWORK")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return false;playLocal(application,ImageSession.current(),ImageSession.entries(),0);return true;}LocalMedia file=LocalAudioService.current();if(file!=null){if(android.os.Build.VERSION.SDK_INT>=37&&application.checkSelfPermission("android.permission.ACCESS_LOCAL_NETWORK")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return false;playLocal(application,file,LocalAudioService.queue(),LocalAudioService.player().getCurrentPosition());return true;}LocalMedia radioFile=RadioPlaybackService.selectedFile();if(radioFile!=null){if(android.os.Build.VERSION.SDK_INT>=37&&application.checkSelfPermission("android.permission.ACCESS_LOCAL_NETWORK")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return false;List<LocalMedia> queue=new ArrayList<>();androidx.media3.common.Player audio=RadioPlaybackService.audioPlayer();if(audio!=null)for(int i=0;i<audio.getMediaItemCount();i++){LocalMedia item=CarAudioCatalog.file(audio.getMediaItemAt(i));if(item!=null)queue.add(item);}playLocal(application,radioFile,queue,audio==null?0:audio.getCurrentPosition());return true;}RadioStation station=RadioPlaybackService.selectedStation();if(station!=null){playRadio(application,station);return true;}return false;}
 public static void playRadio(Context context,RadioStation station){beginSelection();resetFileQueue();castQueue=null;castChannel=null;CastHistory.beforeLoad();artworkStation=station;artworkFile=null;artworkData=null;if(remote(context)!=null){LastAudio.radio(context,station);LocalCastService.castRadio(context,station);}}
 static void loadRadio(Context context,RadioStation station,String logo){final int selectedRequest=selection();RemoteMediaClient remote=remote(context);if(remote==null)return;
  MediaMetadata metadata=new MediaMetadata(MediaMetadata.MEDIA_TYPE_MUSIC_TRACK);metadata.putString(MediaMetadata.KEY_TITLE,station.displayName());metadata.putString(MediaMetadata.KEY_ARTIST,UiText.text(PlaybackText.SOURCE));metadata.putString(MediaMetadata.KEY_SUBTITLE,UiText.text(PlaybackText.SOURCE));if(logo!=null)metadata.addImage(new com.google.android.gms.common.images.WebImage(android.net.Uri.parse(logo)));
  MediaInfo info=new MediaInfo.Builder(station.url).setContentType(station.hls?"application/x-mpegURL":"audio/mpeg").setStreamType(MediaInfo.STREAM_TYPE_LIVE).setMetadata(metadata).build();
  remote.load(new MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true).build()).setResultCallback(result->{if(!selectionCurrent(selectedRequest))return;if(result.getStatus().isSuccess()){localUrls.clear();context.stopService(new Intent(context,RadioPlaybackService.class));}else{failed(context);releaseLocalServer(context);}});
 }
 public static void playLocal(Context context,LocalMedia file,List<LocalMedia> entries,long position){if(!connected(context))return;beginSelection();if(file.audio())LastAudio.file(context,file);int jumpRequest=++fileJumpGeneration;if(!file.image()&&jumpToFile(context,file,position,jumpRequest))return;resetFileQueue();localLoadPending=true;artworkStation=null;artworkFile=file.uri;androidx.media3.exoplayer.ExoPlayer player=LocalAudioService.player();LocalMedia current=LocalAudioService.current();artworkData=current!=null&&current.uri.equals(file.uri)&&player!=null?player.getMediaMetadata().artworkData:null;castQueue=new LocalQueue(entries,file);castChannel=null;LocalCastService.cast(context,castQueue,position);}
 static void loadImage(Context context,LocalMedia file,String url,String mime){final int selectedRequest=selection();CastHistory.beforeLoad();RemoteMediaClient remote=remote(context);if(remote==null)return;localUrls.clear();localUrls.put(file.uri,url);MediaMetadata metadata=new MediaMetadata(MediaMetadata.MEDIA_TYPE_PHOTO);metadata.putString(MediaMetadata.KEY_TITLE,file.displayName());if(metadata.getMediaType()==MediaMetadata.MEDIA_TYPE_MUSIC_TRACK){metadata.putString(MediaMetadata.KEY_ARTIST,UiText.text(PlaybackText.SOURCE));metadata.putString(MediaMetadata.KEY_SUBTITLE,UiText.text(PlaybackText.SOURCE));metadata.putString(MediaMetadata.KEY_ALBUM_TITLE,PlaybackText.shortTitle(file.displayName()));metadata.putString(MediaMetadata.KEY_ALBUM_ARTIST,PlaybackText.shortTitle(file.displayName()));}metadata.addImage(new com.google.android.gms.common.images.WebImage(android.net.Uri.parse(url)));
  MediaInfo info=new MediaInfo.Builder(url).setContentType(mime).setStreamType(MediaInfo.STREAM_TYPE_NONE).setMetadata(metadata).build();remote.load(new MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true).build()).setResultCallback(result->{if(!selectionCurrent(selectedRequest))return;localLoadPending=false;if(!result.getStatus().isSuccess()){failed(context);releaseLocalServer(context);}});
 }
 private static boolean jumpToFile(Context context,LocalMedia file,long position,int jumpRequest){if(localLoadPending)return false;RemoteMediaClient remote=remote(context);String url=localUrls.get(file.uri);if(remote==null||url==null||remote.getMediaStatus()==null)return false;for(MediaQueueItem item:remote.getMediaStatus().getQueueItems())if(item.getMedia()!=null&&Objects.equals(url,item.getMedia().getContentId())){CastHistory.beforeLoad();remote.queueJumpToItem(item.getItemId(),Math.max(0,position),null).setResultCallback(result->{if(jumpRequest==fileJumpGeneration&&result.getStatus().isSuccess())remote.play();});return true;}return false;}
 static void fileArtwork(LocalMedia file,byte[] data){if(data==null||data.length==0||data.length>2*1024*1024)return;fileCovers.put(file.uri,data);String current=null;if(watched!=null&&watched.getMediaInfo()!=null)for(Map.Entry<String,String> entry:localUrls.entrySet())if(Objects.equals(entry.getValue(),watched.getMediaInfo().getContentId())){current=entry.getKey();break;}Iterator<String> keys=fileCovers.keySet().iterator();while(fileCovers.size()>4&&keys.hasNext()){String key=keys.next();if(!Objects.equals(key,current))keys.remove();}}
 static byte[] cachedArtwork(LocalMedia file){return file.uri.equals(artworkFile)?artworkData:null;}
 interface LoadGuard {boolean current();}
 static void loadLocal(Context context,LocalQueue queue,List<String> urls,List<String> logos,long position,LoadGuard valid,Runnable loaded){CastHistory.beforeLoad();RemoteMediaClient remote=remote(context);if(remote==null)return;localUrls.clear();MediaQueueItem[] items=new MediaQueueItem[queue.entries.size()];
  for(int i=0;i<items.length;i++){LocalMedia file=queue.entries.get(i);localUrls.put(file.uri,urls.get(i));MediaMetadata metadata=new MediaMetadata(file.audio()?MediaMetadata.MEDIA_TYPE_MUSIC_TRACK:MediaMetadata.MEDIA_TYPE_MOVIE);metadata.putString(MediaMetadata.KEY_TITLE,file.displayName());if(metadata.getMediaType()==MediaMetadata.MEDIA_TYPE_MUSIC_TRACK){metadata.putString(MediaMetadata.KEY_ARTIST,UiText.text(PlaybackText.SOURCE));metadata.putString(MediaMetadata.KEY_SUBTITLE,UiText.text(PlaybackText.SOURCE));metadata.putString(MediaMetadata.KEY_ALBUM_TITLE,PlaybackText.shortTitle(file.displayName()));metadata.putString(MediaMetadata.KEY_ALBUM_ARTIST,PlaybackText.shortTitle(file.displayName()));}
   SaavnSong song=SaavnMusic.is(file.uri)?SaavnMusic.peek(SaavnMusic.id(file.uri)):null;
   if(song!=null){metadata=new MediaMetadata(MediaMetadata.MEDIA_TYPE_MUSIC_TRACK);metadata.putString(MediaMetadata.KEY_TITLE,song.title);if(!song.artist.isEmpty())metadata.putString(MediaMetadata.KEY_ARTIST,song.artist);if(!song.album.isEmpty())metadata.putString(MediaMetadata.KEY_ALBUM_TITLE,song.album);String subtitle=UiText.text(PlaybackText.SOURCE);if(!song.artist.isEmpty())subtitle+=" · "+song.artist;if(!song.album.isEmpty())subtitle+=" · "+song.album;metadata.putString(MediaMetadata.KEY_SUBTITLE,subtitle);}
   if(logos.get(i)!=null)metadata.addImage(new com.google.android.gms.common.images.WebImage(android.net.Uri.parse(logos.get(i))));
   MediaInfo.Builder media=new MediaInfo.Builder(urls.get(i)).setContentType(mime(file)).setStreamType(MediaInfo.STREAM_TYPE_BUFFERED).setMetadata(metadata);if(song!=null&&song.duration>0)media.setStreamDuration(song.duration*1000);MediaInfo info=media.build();items[i]=new MediaQueueItem.Builder(info).setAutoplay(true).build();}
  CastQueuePlan plan=new CastQueuePlan(items.length,queue.start);queuePlan=plan;queueItems=items;appending=false;
  remote.queueLoad(Arrays.copyOfRange(items,plan.from,plan.to),plan.start,MediaStatus.REPEAT_MODE_REPEAT_OFF,position,null).setResultCallback(result->{if(!valid.current())return;localLoadPending=false;if(result.getStatus().isSuccess()){appendFiles();loaded.run();context.stopService(new Intent(context,LocalAudioService.class));context.stopService(new Intent(context,RadioPlaybackService.class));}else {failed(context);context.stopService(new Intent(context,LocalCastService.class));}});
 }
 static void updateFileArtwork(Context context,String url,String logo){if(queueItems!=null)for(MediaQueueItem pending:queueItems){MediaInfo info=pending.getMedia();if(info!=null&&Objects.equals(url,info.getContentId())&&info.getMetadata()!=null&&info.getMetadata().getImages().isEmpty())info.getMetadata().addImage(new com.google.android.gms.common.images.WebImage(android.net.Uri.parse(logo)));}RemoteMediaClient remote=remote(context);if(remote==null||remote.getMediaStatus()==null)return;for(MediaQueueItem item:remote.getMediaStatus().getQueueItems()){MediaInfo info=item.getMedia();if(info==null||!Objects.equals(url,info.getContentId())||info.getMetadata()==null||!info.getMetadata().getImages().isEmpty())continue;info.getMetadata().addImage(new com.google.android.gms.common.images.WebImage(android.net.Uri.parse(logo)));remote.queueUpdateItems(new MediaQueueItem[]{new MediaQueueItem.Builder(item).build()},null);return;}}
 public static void resetProgress(Context context){CastHistory.reset(context);}
 static String historyKey(Context context){RemoteMediaClient remote=remote(context);if(remote==null||remote.getMediaInfo()==null)return "";String id=remote.getMediaInfo().getContentId();for(Map.Entry<String,String> entry:localUrls.entrySet())if(java.util.Objects.equals(entry.getValue(),id))return entry.getKey();return id==null?"":id;}
 static String mime(LocalMedia file){int dot=file.name.lastIndexOf('.');String extension=dot<0?"":file.name.substring(dot+1);String inferred=android.webkit.MimeTypeMap.getSingleton().getMimeTypeFromExtension(extension.toLowerCase(Locale.ROOT));return inferred!=null?inferred:!file.mime.isEmpty()&&!file.mime.equals("application/octet-stream")?file.mime:file.audio()?"audio/mpeg":"video/mp4";}
 static FavoriteLists.Item downloadItem(Context context){RemoteMediaClient remote=remote(context);if(remote==null||remote.getMediaInfo()==null||remote.isLiveStream())return null;String url=remote.getMediaInfo().getContentId();if(castQueue!=null)for(LocalMedia file:castQueue.entries)if(Objects.equals(localUrls.get(file.uri),url))return FavoriteLists.of(file);return castChannel!=null&&castChannel.kind!=Playlist.Kind.TV?FavoriteLists.of(new Library.Entry("",castChannel)):null;}
 static Object phoneArtwork(Context context){for(Map.Entry<String,String> entry:localUrls.entrySet())if(currentLocal(context,entry.getKey())){LocalMedia file=null;if(castQueue!=null)for(LocalMedia candidate:castQueue.entries)if(candidate.uri.equals(entry.getKey())){file=candidate;break;}String cover=LocalFileArtwork.asset(file!=null?file:new LocalMedia(entry.getKey(),title(context),"audio/mpeg",false));if(cover!=null)return cover;byte[] data=fileCovers.get(entry.getKey());if(data!=null)return data;}if(artworkStation!=null&&title(context).equals(artworkStation.displayName()))return PlaybackArtwork.radioModel(context,artworkStation);return artworkFile!=null&&currentLocal(context,artworkFile)?artworkData:null;}
 static void failed(Context context){UiText.toast(context,"Cast-enheden kunne ikke afspille indholdet. Kontrollér netværk og filformat.",android.widget.Toast.LENGTH_LONG).show();}
}
